contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);
        c.Put{value: putAmount}(unlockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        if (beforeBalance < c.MinSum()) {
            bool reverted;
            try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
            assert(reverted);

            (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
            assert(afterBalance == beforeBalance);
            assert(address(c).balance == cBalanceBefore);
            assert(address(this).balance == thisBalanceBefore);
        } else {
            if (collectAmount <= beforeBalance && block.timestamp > beforeUnlockTime) {
                bool reverted;
                try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

                if (reverted) {
                    assert(address(c).balance < collectAmount);
                } else {
                    (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
                    assert(afterBalance == beforeBalance - collectAmount);
                    assert(address(c).balance == cBalanceBefore - collectAmount);
                    assert(address(this).balance == thisBalanceBefore + collectAmount);
                }
            }
        }
    }

    receive() external payable {}
}

