contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _unlockTime, uint _putAmount, uint _collectAmount) public payable {
        require(address(this).balance >= _putAmount, "not enough eth");
        require(_putAmount > 0, "put must be positive");

        c.Put{value: _putAmount}(_unlockTime);

        uint accBalanceBefore;
        uint accUnlockBefore;
        (accUnlockBefore, accBalanceBefore) = c.Acc(address(this));

        uint contractBalanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        bool reverted;
