            assert(accBalanceAfter == accBalanceBefore - _collectAmount);
            assert(accUnlockAfter == accUnlockBefore);
            assert(address(c).balance == contractBalanceBefore - _collectAmount);
            assert(address(this).balance == callerBalanceBefore + _collectAmount);
        } else {
            assert(accBalanceAfter == accBalanceBefore);
            assert(accUnlockAfter == accUnlockBefore);
            assert(address(c).balance == contractBalanceBefore);
            assert(address(this).balance == callerBalanceBefore);
        }
    }

    receive() external payable {}
