contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        c.Put{value: putAmount}(unlockTime);
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        require(afterBalance == beforeBalance + putAmount);
        require(afterUnlock == (unlockTime > block.timestamp ? unlockTime : block.timestamp));

        require(address(c).balance >= collectAmount);
        bool collectReverted;
        uint beforeCollectBalance = afterBalance;
        uint beforeContractBalance = address(c).balance;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint finalContractBalance = address(c).balance;

        assert(
            collectReverted
                ? (finalBalance == beforeCollectBalance && address(this).balance == 0 && finalContractBalance == beforeContractBalance)
                : (finalBalance == beforeCollectBalance - collectAmount && address(this).balance == collectAmount && finalContractBalance == beforeContractBalance - collectAmount)
        );
    }

    receive() external payable {}
}

